// Import style
import './style.scss';

// Import global utils
import { isDefined } from '@automator/shared/utils/is-defined';

// Import dom-ready
import domReady from '@wordpress/dom-ready';

// Import images
import './img/delay-or-schedule-actions-landscape-2-2x.png';
import './img/delay-or-schedule-actions-2-2x.png';
import './img/multiple-actions-landscape-2-2x.png';
import './img/multiple-actions-2-2x.png';
import './img/multiple-triggers-landscape-2-2x.png';
import './img/multiple-triggers-2-2x.png';

const OPEN_AGENT_PARAMETER = 'automator_open_agent';
const AGENT_WAIT_TIMEOUT = 4000;
const AGENT_POLL_INTERVAL = 100;

/**
 * Class representing the Dashboard page.
 */
export default class Dashboard {
	/**
	 * Initializes the Dashboard page.
	 */
	constructor() {

		if ( this.isDashboardPage && this.shouldOpenAgent ) {
			this.openAgent();
		}
	}

	/**
	 * Determines if the current page is the "Dashboard" page.
	 *
	 * @return {Boolean} True if the current page is the "Dashboard" page.
	 */
	get isDashboardPage() {
		return isDefined( document.getElementById( 'uap-dashboard' ) );
	}

	/**
	 * Determines whether the setup wizard requested Uncanny Agent.
	 *
	 * @return {Boolean} True when the Agent panel must open.
	 */
	get shouldOpenAgent() {

		return new URLSearchParams( window.location.search ).get( OPEN_AGENT_PARAMETER ) === '1';
	}

	/**
	 * Opens Uncanny Agent through its public API.
	 */
	async openAgent() {

		const agent = await this.waitForAgent();

		if ( ! agent ) {
			return;
		}

		try {
			await agent.ready;
			await agent.open( {
				placement: 'docked',
				focus: true,
			} );
		} catch ( error ) {
			return;
		}
	}

	/**
	 * Waits for the Agent API to become available.
	 *
	 * @return {Promise<Object|null>} The Agent API.
	 */
	waitForAgent() {

		return new Promise( ( resolve ) => {
			if ( window.UncannyAgent ) {
				resolve( window.UncannyAgent );
				return;
			}

			const deadline = Date.now() + AGENT_WAIT_TIMEOUT;
			const poll = setInterval( () => {
				if ( window.UncannyAgent ) {
					clearInterval( poll );
					resolve( window.UncannyAgent );
					return;
				}

				if ( Date.now() > deadline ) {
					clearInterval( poll );
					resolve( null );
				}
			}, AGENT_POLL_INTERVAL );
		} );
	}

}

domReady( () => {
	new Dashboard();
} );
