/**
 * Service for the `resend_failed_list` REST route.
 *
 * Returns a keyset-paginated page of failed App actions (200 per page,
 * server-enforced) for the selectable table: the rows plus the total count and
 * a cursor / `hasMore` flag so the caller can load more.
 */
// Import HTTP helper
import { postToAutomator } from '../http';
// Import coercion helpers
import { normalizeDays, toCount, toBool, toCursor, toText } from '../coerce';
/**
 * Normalizes a raw row record into a {@link FailedActionRow}.
 *
 * @param raw The row record from the wire.
 * @return The normalized row.
 */
function normalizeRow(raw) {
    return {
        actionLogId: toCount(raw.action_log_id),
        recipeId: toCount(raw.recipe_id),
        recipeTitle: toText(raw.recipe_title),
        userId: toCount(raw.user_id),
        userName: toText(raw.user_name),
        userEmail: toText(raw.user_email),
        recipeLogId: toCount(raw.recipe_log_id),
        runNumber: toCount(raw.run_number),
        failDate: toText(raw.fail_date),
        endpoint: toText(raw.endpoint),
        failReason: toText(raw.fail_reason),
        status: toText(raw.status),
        resentCount: toCount(raw.resent_count),
        logsUrl: toText(raw.logs_url),
    };
}
/**
 * Lists a single page of failed App actions and returns normalized rows.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param args The look-back window and optional cursor.
 * @return The normalized list result.
 */
export async function listFailedActions(args) {
    const endpoint = (args.endpoint ?? '').trim();
    const response = await postToAutomator('resend_failed_list', {
        days: normalizeDays(args.days),
        // eslint-disable-next-line camelcase
        last_id: toCursor(args.lastId ?? 0),
        // Only send the filter when set; an empty string means "all endpoints".
        ...(endpoint !== '' ? { endpoint } : {}),
    });
    const rawRows = Array.isArray(response.rows) ? response.rows : [];
    const rows = rawRows.map((row) => normalizeRow(row));
    const rawEndpoints = Array.isArray(response.endpoints) ? response.endpoints : [];
    const endpoints = rawEndpoints.map((value) => toText(value));
    return {
        total: toCount(response.total),
        lastId: toCursor(response.last_id),
        hasMore: toBool(response.has_more),
        rows,
        endpoints,
    };
}
export * from './types';
