/**
 * Service for the `resend_failed_run` REST route.
 *
 * Re-fires exactly the provided action log ids (blocking-sequential, server
 * side) and returns the tally plus a per-action outcome for each requested id.
 */
// Import HTTP helper
import { postToAutomator } from '../http';
// Import coercion helpers
import { toCount, toText } from '../coerce';
// Import types
import { ResendOutcome } from './types';
/**
 * Coerces an unknown value to a {@link ResendOutcome}, defaulting to `skipped`.
 *
 * @param value The raw outcome from the wire.
 * @return A valid outcome literal.
 */
function toOutcome(value) {
    if (value === ResendOutcome.RESENT || value === ResendOutcome.FAILED) {
        return value;
    }
    return ResendOutcome.SKIPPED;
}
/**
 * Normalizes a raw per-action result into a {@link ResendActionResult}.
 *
 * @param raw The result record from the wire.
 * @return The normalized result.
 */
function normalizeResult(raw) {
    return {
        actionLogId: toCount(raw.action_log_id),
        outcome: toOutcome(raw.outcome),
        message: toText(raw.message),
    };
}
/**
 * Resends the selected failed App actions and returns normalized totals.
 *
 * @since 7.3.2 Initial implementation.
 * @since 7.3.2 Posts `action_log_ids` and returns per-action results (v2).
 *
 * @param args The checked action log ids.
 * @return The normalized run result.
 */
export async function runFailedActions(args) {
    const actionLogIds = args.actionLogIds
        .map((id) => toCount(id))
        .filter((id) => id > 0);
    const response = await postToAutomator('resend_failed_run', {
        // eslint-disable-next-line camelcase
        action_log_ids: actionLogIds,
    });
    const rawResults = Array.isArray(response.results) ? response.results : [];
    const results = rawResults.map((result) => normalizeResult(result));
    return {
        resent: toCount(response.resent),
        failed: toCount(response.failed),
        skipped: toCount(response.skipped),
        results,
    };
}
export * from './types';
