/**
 * Shared HTTP helper for the recipe-domain resend-failed-actions services.
 *
 * Mirrors the per-action Resend button: it registers the WordPress REST nonce
 * middleware once and POSTs to a route under the Automator REST namespace
 * exposed on `window.UncannyAutomatorBackend.rest`.
 */
// Import dependencies
import apiFetch from '@wordpress/api-fetch';
/**
 * Reads the Automator REST config off the global backend object.
 *
 * @return The REST config, with empty strings when the global is absent.
 */
function getRestConfig() {
    const hasBackend = typeof UncannyAutomatorBackend !== 'undefined';
    const rest = hasBackend && UncannyAutomatorBackend.rest ? UncannyAutomatorBackend.rest : {};
    return {
        url: typeof rest.url === 'string' ? rest.url : '',
        nonce: typeof rest.nonce === 'string' ? rest.nonce : '',
    };
}
let nonceRegistered = false;
/**
 * Registers the REST nonce middleware exactly once so every request carries the
 * `X-WP-Nonce` header. Safe to call repeatedly.
 *
 * @since 7.3.2 Initial implementation.
 */
export function ensureNonceMiddleware() {
    if (nonceRegistered) {
        return;
    }
    const { nonce } = getRestConfig();
    if (nonce) {
        apiFetch.use(apiFetch.createNonceMiddleware(nonce));
        nonceRegistered = true;
    }
}
/**
 * POSTs a JSON body to a route under the Automator REST namespace.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param route The route name (e.g. `resend_failed_list`).
 * @param data  The request body.
 * @return The parsed JSON response.
 */
export async function postToAutomator(route, data) {
    ensureNonceMiddleware();
    const { url } = getRestConfig();
    return apiFetch({
        url: `${url}/${route}`,
        method: 'POST',
        data,
    });
}
