/**
 * Plain coercion helpers shared by the recipe-domain resend-failed-actions services.
 *
 * The REST layer returns integers/booleans, but a defensive client must not
 * trust the wire shape. Zod is unavailable on this branch, so these helpers
 * normalize unknown response fields without a schema library.
 */
/**
 * Coerces an unknown value to a non-negative integer, defaulting to 0.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param value The raw value from the response.
 * @return A finite non-negative integer.
 */
export function toCount(value) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed) || parsed < 0) {
        return 0;
    }
    return Math.floor(parsed);
}
/**
 * Coerces an unknown value to a string, defaulting to an empty string.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param value The raw value from the response.
 * @return The string interpretation, or '' for null/undefined.
 */
export function toText(value) {
    if (value === null || typeof value === 'undefined') {
        return '';
    }
    return String(value);
}
/**
 * Coerces an unknown value to a boolean using truthiness.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param value The raw value from the response.
 * @return The boolean interpretation of the value.
 */
export function toBool(value) {
    return Boolean(value);
}
/**
 * Clamps the look-back days to the supported 1-365 window, defaulting to 7.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param days The requested number of days.
 * @return A clamped integer in [1, 365].
 */
export function normalizeDays(days) {
    const parsed = Math.floor(Number(days));
    if (!Number.isFinite(parsed) || parsed < 1) {
        return 7;
    }
    return Math.min(365, parsed);
}
/**
 * Coerces an unknown cursor value to a non-negative integer.
 *
 * @since 7.3.2 Initial implementation.
 *
 * @param value The raw value (often a string id from the wire).
 * @return A finite non-negative integer.
 */
export function toCursor(value) {
    return toCount(value);
}
